function toRad(d){ return d*Math.PI/180; }
function toDeg(r){ return r*180/Math.PI; }
function sin(x,deg){ return Math.sin(deg?toRad(x):x); }
function cos(x,deg){ return Math.cos(deg?toRad(x):x); }
function tan(x,deg){ return Math.tan(deg?toRad(x):x); }
function asin(x,deg){ var r=Math.asin(Math.max(-1,Math.min(1,x))); return deg?toDeg(r):r; }
function acos(x,deg){ var r=Math.acos(Math.max(-1,Math.min(1,x))); return deg?toDeg(r):r; }
function atan(x,deg){ var r=Math.atan(x); return deg?toDeg(r):r; }
function atan2(y,x,deg){ var r=Math.atan2(y,x); return deg?toDeg(r):r; }
var EXPORTS={ toRad:toRad, toDeg:toDeg, sin:sin, cos:cos, tan:tan, asin:asin, acos:acos, atan:atan, atan2:atan2 };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
